signin_callback_verification.code:
async signIn({ user, account, profile }) {
  if (account?.provider === 'google-one-tap') {
    const credential = user.email
    if (!credential || credential.length < 100) return false

    try {
      const ticket = await googleAuthClient.verifyIdToken({
        idToken: credential,
        audience: process.env.AUTH_GOOGLE_ID,
      })
      const payload = ticket.getPayload()
      if (!payload) return false

      // Update user object with verified Google data
      user.id = payload.sub
      user.email = payload.email || ''
      user.name = payload.name || ''
      user.image = payload.picture || null
      ;(user as any).emailVerified = payload.email_verified ? new Date() : null

      return true
    } catch (error) {
      logger.error('Google token verification failed:', error)
      return false
    }
  }
  return true
}

credentials_provider_config.code:
CredentialsProvider({
  id: 'crypto-wallet',
  name: 'Crypto Wallet',
  credentials: {
    walletAddress: { label: 'Wallet Address', type: 'text' },
    signedNonce: { label: 'Signed Nonce', type: 'text' },
  },
  async authorize(credentials) {
    if (!credentials) return null
    const { walletAddress, signedNonce } = credentials

    try {
      // Fetch stored nonce from database
      const userDoc = await db.collection('users').doc(walletAddress).get()
      const userData = userDoc.data()
      if (!userData || !userData.nonce) return null

      // Verify signature with viem
      const signerAddress = verifyMessage({
        address: walletAddress as `0x${string}`,
        message: userData.nonce,
        signature: signedNonce as `0x${string}`,
      })
      if (signerAddress !== walletAddress) return null

      // Check nonce expiry
      if (userData.nonceExpires && userData.nonceExpires < Date.now()) return null

      // Clear nonce to prevent replay attacks
      await userDoc.ref.update({ nonce: null, nonceExpires: null })

      return {
        id: String(walletAddress),
        email: String(userData.email || ''),
        name: userData.name || null,
        image: userData.photoURL || null,
        role: userData.role || UserRole.SUBSCRIBER,
        isVerified: !!userData.isVerified,
      }
    } catch (error) {
      logger.error('Crypto wallet auth error:', error)
      return null
    }
  },
})

