edge_jwt_utilities.code_example:
import { SignJWT, jwtVerify } from 'jose'

const getJwtSecret = () => {
  const secret = process.env.AUTH_SECRET || process.env.NEXTAUTH_SECRET
  if (!secret) throw new Error('AUTH_SECRET must be set')
  return new TextEncoder().encode(secret)
}

export async function verifyJWT(token: string) {
  const { payload } = await jwtVerify(token, getJwtSecret(), { algorithms: ['HS256'] })
  return { userId: payload.sub, email: payload.email as string }
}

export async function createJWT(userId: string, email?: string) {
  return new SignJWT({ sub: userId, email, purpose: 'tunnel-auth' })
    .setProtectedHeader({ alg: 'HS256' })
    .setIssuedAt()
    .setExpirationTime('24h')
    .sign(getJwtSecret())
}

middleware_auth_caching.code_example:
interface AuthCacheEntry {
  userId: string
  role: UserRole
  expires: number
  ipAddress: string  // SECURITY: Bind cache to IP to prevent session hijacking
}

const authCache = new Map<string, AuthCacheEntry>()
const CACHE_TTL = 30000 // 30 seconds

function cleanExpiredCache() {
  const now = Date.now()
  for (const [key, value] of authCache.entries()) {
    if (value.expires < now) authCache.delete(key)
  }
  // Keep cache manageable in Edge runtime
  if (authCache.size > 1000) {
    const entries = Array.from(authCache.entries())
    entries.sort((a, b) => a[1].expires - b[1].expires)
    entries.slice(0, Math.floor(entries.length * 0.25)).forEach(([key]) => authCache.delete(key))
  }
}

