let cachedAdapter: any = null
let adapterType: 'postgresql' | 'firebase' | null = null

export function getAuthAdapter() {
  const { shouldUseFirebaseForDatabase } = require('./database/backend-mode-config')
  const usePostgreSQL = !shouldUseFirebaseForDatabase()
  const newAdapterType = usePostgreSQL ? 'postgresql' : 'firebase'

  if (cachedAdapter && adapterType === newAdapterType) return cachedAdapter

  if (usePostgreSQL) {
    cachedAdapter = PostgreSQLAdapter()
    adapterType = 'postgresql'
  } else {
    cachedAdapter = FirestoreAdapter(getAdminDb())
    adapterType = 'firebase'
  }
  return cachedAdapter
}

